-- 556: Original BrillaPrep WASSCE Social Studies sprint 3 beta questions, part 3 of 15 (batch wassce-social-studies-sprint3-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_556_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_556_guard;
INSERT INTO _migration_556_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_009' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_civ' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the minimum age at which a Ghanaian citizen may register to vote in public elections?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 18 years","B. 16 years","C. 21 years","D. 25 years"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Article 42 of the 1992 Constitution grants the vote to every citizen of Ghana who is eighteen years or above and of sound mind. (16 is below the legal age of majority; 21 confuses voting with older historical thresholds; 25 is the minimum age for election to Parliament, not for voting.) Therefore the correct answer is A: 18 years.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_009' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_556_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_010' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_civ' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which body is responsible for conducting and supervising all public elections and referenda in Ghana?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The National Commission for Civic Education","B. The Electoral Commission","C. The Judicial Service","D. The Ministry of the Interior"]' AND q.correct_answer IS 'B' AND q.explanation IS 'The Electoral Commission of Ghana, established under Article 43 of the 1992 Constitution, registers voters, demarcates constituencies and conducts elections. (The NCCE only educates citizens on their civic duties, the Judicial Service administers the courts, and the Ministry of the Interior handles internal security — none conducts elections.) Therefore the correct answer is B: The Electoral Commission.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_010' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_556_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_011' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_civ' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The right of qualified citizens to vote in elections is known as...' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A referendum","B. Naturalization","C. The franchise","D. A census"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The franchise (or suffrage) is the right to vote in public elections. A referendum is a vote on a single national question, naturalization is the legal process of acquiring citizenship, and a census is an official population count — none of them names the right to vote itself. Therefore the correct answer is C: The franchise.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_011' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_556_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_soc_s3_012' AND NOT (q.topic_id IS 'topic_wassce_p2_soc_civ' AND q.subject_id IS 'subj_wassce_social' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is a civic responsibility of a Ghanaian citizen?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Evading taxes when business is slow","B. Refusing to obey lawful court orders","C. Destroying posters of rival political parties","D. Paying taxes honestly and promptly"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Civic responsibilities include paying taxes, voting, obeying the law and defending the state. Tax revenue funds schools, hospitals and roads. (Tax evasion, defying court orders and destroying opponents’ campaign materials are all unlawful acts that undermine civic life.) Therefore the correct answer is D: Paying taxes honestly and promptly.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Select' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_soc_s3_012' AND NOT (r.batch_id IS 'wassce-social-studies-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Social Studies practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_009', 'topic_wassce_p2_soc_civ', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'What is the minimum age at which a Ghanaian citizen may register to vote in public elections?', 'multiple_choice', NULL, '["A. 18 years","B. 16 years","C. 21 years","D. 25 years"]', 'A', 'Article 42 of the 1992 Constitution grants the vote to every citizen of Ghana who is eighteen years or above and of sound mind. (16 is below the legal age of majority; 21 confuses voting with older historical thresholds; 25 is the minimum age for election to Parliament, not for voting.) Therefore the correct answer is A: 18 years.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec');
