INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_soc_s3_012', 'topic_wassce_p2_soc_civ', 'subj_wassce_social', 'exam_wassce', NULL, NULL, 'Which of the following is a civic responsibility of a Ghanaian citizen?', 'multiple_choice', NULL, '["A. Evading taxes when business is slow","B. Refusing to obey lawful court orders","C. Destroying posters of rival political parties","D. Paying taxes honestly and promptly"]', 'D', 'Civic responsibilities include paying taxes, voting, obeying the law and defending the state. Tax revenue funds schools, hospitals and roads. (Tax evasion, defying court orders and destroying opponents’ campaign materials are all unlawful acts that undermine civic life.) Therefore the correct answer is D: Paying taxes honestly and promptly.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Select', 'AO1', NULL, NULL, 'board_waec');
